// === profile.js ===
/* ============================================
   PROFILE SECTION - Dynamic data loading from JSON
   ============================================ */

let profileData = null;
let aboutModalData = null;
let contactsData = null;
let resumeData = null;

/**
 * Get base path for GitHub Pages compatibility
 */
function getBasePath() {
    return window.location.pathname.includes('/skywireneo.github.io')
        ? '/skywireneo.github.io'
        : '';
}

/**
 * Load profile data from JSON
 */
async function loadProfileData() {
    try {
        const basePath = getBasePath();

        // Load contacts.json (profile + resume + contacts)
        const contactsUrl = `${basePath}/_data/contacts.json`;
        const contactsResponse = await fetch(contactsUrl);
        if (!contactsResponse.ok) {
            throw new Error('Failed to load contacts.json');
        }
        const contactsJson = await contactsResponse.json();
        profileData = contactsJson.profile || null;
        resumeData = contactsJson.resume || null;
        contactsData = contactsJson.contacts || [];

        // Load about.json (resumeModal)
        const aboutUrl = `${basePath}/_data/about.json`;
        const aboutResponse = await fetch(aboutUrl);
        if (!aboutResponse.ok) {
            throw new Error('Failed to load about.json');
        }
        const aboutJson = await aboutResponse.json();
        aboutModalData = aboutJson.resumeModal || null;

        // Render all sections
        renderHeader();
        renderContacts();
        renderResumeModal();
        initResumeButton();
        initCopyEmailButton();

    } catch (error) {
        console.error('Profile: failed to load data', error);
    }
}

/**
 * Get status CSS class based on status text
 */
function getStatusClass(status) {
    const statusClasses = {
        'Открыт к предложениям': 'status-open',
        'В поиске работы': 'status-searching',
        'Рассматриваю предложения': 'status-considering',
        'Занят на проекте': 'status-busy',
        'Не ищу работу': 'status-not-looking',
        'В отпуске': 'status-vacation'
    };

    return statusClasses[status] || '';
}

/**
 * Render header section
 */
function renderHeader() {
    if (!profileData) return;

    // Avatar
    const avatarImg = document.querySelector('[data-avatar]');
    if (avatarImg && profileData.avatar) {
        avatarImg.src = profileData.avatar;
        avatarImg.alt = `${profileData.name} ${profileData.nickname}`;
    }

    // Name
    const nameEl = document.getElementById('profileName');
    if (nameEl && profileData.name && profileData.nickname) {
        nameEl.textContent = `${profileData.name} ${profileData.nickname}`;
    }

    // Title
    const titleEl = document.getElementById('profileTitle');
    if (titleEl && profileData.title) {
        titleEl.textContent = profileData.title;
    }

    // Location
    const locationEl = document.getElementById('profileLocation');
    if (locationEl && profileData.location) {
        locationEl.textContent = profileData.location;
    }

    // Status with dynamic CSS class
    const statusEl = document.getElementById('profileStatus');
    if (statusEl && profileData.status) {
        statusEl.textContent = profileData.status;
        // Remove old status classes
        statusEl.classList.remove('status-open', 'status-searching', 'status-considering', 'status-busy', 'status-not-looking', 'status-vacation');
        // Add new status class
        const statusClass = getStatusClass(profileData.status);
        if (statusClass) {
            statusEl.classList.add(statusClass);
        }
    }

    // Resume button text
    const resumeBtnText = document.getElementById('resumeBtnText');
    if (resumeBtnText && aboutModalData && aboutModalData.resumeButtonText) {
        resumeBtnText.textContent = aboutModalData.resumeButtonText;
    }
}

/**
 * Render contacts from JSON
 */
function renderContacts() {
    if (!contactsData || contactsData.length === 0) return;

    // Filter primary contacts and sort by order
    const primaryContacts = contactsData
        .filter(contact => contact.isPrimary)
        .sort((a, b) => (a.order || 0) - (b.order || 0));

    const container = document.getElementById('profileContacts');
    if (!container) return;

    // Clear container
    container.innerHTML = '';

    // Render each contact
    primaryContacts.forEach(contact => {
        // Email has special design with copy button
        if (contact.id === 'email') {
            const emailEl = document.createElement('div');
            emailEl.className = 'contact-link email-with-copy';
            emailEl.innerHTML = `
                <a href="${contact.url}" class="email-highlight">
                    <i class="${contact.icon}"></i> <span>${resumeData?.email || 'skywireneo@yandex.ru'}</span>
                </a>
                <button class="copy-email-btn" onclick="copyEmail()" title="Копировать почту">
                    <i class="fas fa-copy"></i>
                </button>
            `;
            container.appendChild(emailEl);
        } else {
            // Regular contact link
            const linkEl = document.createElement('a');
            linkEl.href = contact.url;
            linkEl.target = '_blank';
            linkEl.className = 'contact-link';
            linkEl.innerHTML = `<i class="${contact.icon}"></i> <span>${contact.name}</span>`;
            container.appendChild(linkEl);
        }
    });

    // Add resume button at the end
    const resumeBtn = document.createElement('a');
    resumeBtn.href = '#';
    resumeBtn.id = 'resumeDownloadBtn';
    resumeBtn.className = 'contact-link resume-btn';
    const btnText = (aboutModalData && aboutModalData.resumeButtonText) ? aboutModalData.resumeButtonText : 'Резюме';
    resumeBtn.innerHTML = `<i class="fas fa-download"></i> <span>${btnText}</span>`;
    container.appendChild(resumeBtn);

}


/**
 * Render resume modal
 */
function renderResumeModal() {
    if (!aboutModalData || !resumeData) return;

    // Modal title
    const modalTitle = document.getElementById('resumeModalTitle');
    if (modalTitle && aboutModalData.title) {
        modalTitle.innerHTML = `<i class="fas fa-shield-alt" style="color: var(--accent); margin-right: 0.5rem;"></i>${aboutModalData.title}`;
    }

    // Modal description paragraphs
    const modalDesc1 = document.getElementById('resumeModalDesc1');
    if (modalDesc1 && aboutModalData.description) {
        modalDesc1.textContent = aboutModalData.description;
    }

    const modalDesc2 = document.getElementById('resumeModalDesc2');
    if (modalDesc2 && aboutModalData.note) {
        modalDesc2.textContent = aboutModalData.note;
    }

    // Hint text
    const modalHint = document.getElementById('resumeModalHint');
    if (modalHint && aboutModalData.hint) {
        modalHint.innerHTML = `<i class="fas fa-info-circle" style="margin-right: 0.3rem;"></i>${aboutModalData.hint}`;
    }

    // Email text
    const emailText = document.getElementById('resumeModalEmail');
    if (emailText && resumeData.email) {
        emailText.textContent = resumeData.email;
    }

    // Download link
    const downloadLink = document.getElementById('resumeDownloadLink');
    if (downloadLink && resumeData.path) {
        downloadLink.href = resumeData.path;
        if (aboutModalData.downloadButtonText) {
            downloadLink.innerHTML = `<i class="fas fa-download"></i> ${aboutModalData.downloadButtonText}`;
        }
    }
}

/**
 * Initialize resume button click handler
 */
function initResumeButton() {
    const resumeBtn = document.getElementById('resumeDownloadBtn');
    const resumeModal = document.getElementById('resumeModal');

    if (resumeBtn && resumeModal) {
        resumeBtn.addEventListener('click', (e) => {
            e.preventDefault();
            resumeModal.style.display = 'flex';
            setTimeout(() => {
                resumeModal.classList.add('active');
            }, 10);
        });
    }

    // Close buttons
    const closeBtn = document.getElementById('modalClose');
    const closeBtn2 = document.getElementById('modalCloseBtn');
    const modalOverlay = document.getElementById('resumeModal');

    const closeModal = () => {
        if (resumeModal) {
            resumeModal.classList.remove('active');
            setTimeout(() => {
                resumeModal.style.display = 'none';
            }, 300);
        }
    };

    if (closeBtn) closeBtn.addEventListener('click', closeModal);
    if (closeBtn2) closeBtn2.addEventListener('click', closeModal);
    if (modalOverlay) {
        modalOverlay.addEventListener('click', (e) => {
            if (e.target === modalOverlay) closeModal();
        });
    }
}

/**
 * Initialize copy email button in modal
 */
function initCopyEmailButton() {
    const copyBtn = document.getElementById('copyEmail');
    if (copyBtn) {
        copyBtn.addEventListener('click', copyEmail);
    }
}

/**
 * Copy email to clipboard
 */
function copyEmail() {
    const emailText = document.getElementById('resumeModalEmail');
    const email = emailText ? emailText.textContent : 'skywireneo@yandex.ru';

    navigator.clipboard.writeText(email).then(() => {
        // Update all copy buttons
        const buttons = document.querySelectorAll('.copy-email-btn, .copy-btn-large, #copyEmail');
        buttons.forEach(btn => {
            const originalIcon = btn.innerHTML;
            btn.innerHTML = '<i class="fas fa-check"></i>';
            btn.style.background = 'var(--accent)';
            btn.style.color = '#fff';
            setTimeout(() => {
                btn.innerHTML = originalIcon;
                btn.style.background = '';
                btn.style.color = '';
            }, 1500);
        });
    }).catch(err => {
        console.error('Failed to copy:', err);
    });
}

// Initialize on DOM ready
document.addEventListener('DOMContentLoaded', () => {
    loadProfileData();
});

// Export for potential use
window.loadProfileData = loadProfileData;
window.copyEmail = copyEmail;


// === about.js ===
/* ============================================
   ABOUT SECTION - Dynamic data loading from JSON
   ============================================ */

let aboutData = null;
let technologiesData = null;
let aboutProjectsData = null;



/**
 * Get base path for GitHub Pages compatibility
 */
function getBasePath() {
    return window.location.pathname.includes('/skywireneo.github.io')
        ? '/skywireneo.github.io'
        : '';
}

/**
 * Load all required data
 */
async function loadAboutData() {
    try {
        const basePath = getBasePath();

        // Load about.json
        const aboutUrl = `${basePath}/_data/about.json`;
        const aboutResponse = await fetch(aboutUrl);
        if (!aboutResponse.ok) {
            throw new Error('Failed to load about.json');
        }
        aboutData = await aboutResponse.json();

        // Load technologies.json
        const techUrl = `${basePath}/_data/technologies.json`;
        const techResponse = await fetch(techUrl);
        if (!techResponse.ok) {
            throw new Error('Failed to load technologies.json');
        }
        const techJson = await techResponse.json();
        technologiesData = {};
        techJson.technologies.forEach(tech => {
            technologiesData[tech.id] = tech;
        });

        // Load projects.json
        const projUrl = `${basePath}/_data/projects.json`;
        const projResponse = await fetch(projUrl);
        if (!projResponse.ok) {
            throw new Error('Failed to load projects.json');
        }
        aboutProjectsData = await projResponse.json();


        // Render all sections
        renderFacts();
        renderMainStackTags();
        renderMainStackSkills();
        renderCounterLabels();
        renderTechCounter();
        renderLanguagesCounter();
        renderExperienceCounter();
        renderProjectsCounter();


    } catch (error) {
        console.error('About: failed to load data', error);
    }
}


/**
 * Render facts list
 */
function renderFacts() {
    const container = document.getElementById('aboutFacts');
    if (!container || !aboutData || !aboutData.facts) return;

    const ul = document.createElement('ul');
    ul.className = 'about-list';

    aboutData.facts.forEach(fact => {
        const li = document.createElement('li');
        li.innerHTML = `<i class="${fact.icon}"></i>${fact.text}`;
        ul.appendChild(li);
    });

    container.appendChild(ul);
}

/**
 * Get main stack technologies from technologies.json (filter by isMainStack flag)
 */
function getMainStackTechnologies() {
    if (!technologiesData) return [];

    return Object.values(technologiesData).filter(tech =>
        tech.flags && tech.flags.isMainStack === true
    );
}

/**
 * Render main stack tech tags (clickable)
 */
function renderMainStackTags() {
    const container = document.getElementById('mainStackTags');
    if (!container || !technologiesData) return;

    const mainStack = getMainStackTechnologies();
    if (mainStack.length === 0) return;

    const div = document.createElement('div');
    div.className = 'tech-tags';

    mainStack.forEach(tech => {
        const span = document.createElement('span');
        span.className = 'tech-tag';
        span.setAttribute('data-tech', tech.id);
        span.setAttribute('data-tooltip', tech.tooltip || '');
        span.textContent = tech.name;

        // Apply dynamic color from technology
        if (tech.color) {
            span.style.setProperty('--tech-color', tech.color, 'important');
        }

        div.appendChild(span);
    });

    container.appendChild(div);

    // Re-initialize click handlers for tech tags
    initTechTagHandlers();
}

/**
 * Wait for tech-modal.js to load data
 */
async function waitForTechData(maxAttempts = 50) {
    for (let i = 0; i < maxAttempts; i++) {
        if (window.techData && Object.keys(window.techData).length > 0) {
            return window.techData;
        }
        await new Promise(resolve => setTimeout(resolve, 100));
    }
    return null;
}

/**
 * Initialize click handlers for tech tags (similar to tech-modal.js)
 */
async function initTechTagHandlers() {
    const techTags = document.querySelectorAll('#mainStackTags .tech-tag');

    // Wait for tech-modal.js to load data first
    await waitForTechData();

    techTags.forEach(tag => {
        tag.addEventListener('click', (e) => {
            e.preventDefault();
            e.stopPropagation();
            const techId = tag.getAttribute('data-tech');
            if (techId && typeof window.openTechModal === 'function') {
                window.openTechModal(techId);
            } else {
                console.warn('openTechModal not available yet');
            }
        });

        tag.style.cursor = 'pointer';
    });
}

/**
 * Render main stack skill bars
 */
function renderMainStackSkills() {
    const container = document.getElementById('mainStackSkills');
    if (!container || !technologiesData) return;

    const mainStack = getMainStackTechnologies();
    if (mainStack.length === 0) return;

    const div = document.createElement('div');
    div.className = 'skill-bar-container';

    mainStack.forEach((tech, index) => {
        if (!tech.details) return;

        const level = tech.details.level || 0;
        const levelText = tech.details.levelText || '';
        const color = tech.color || 'var(--accent)';
        const icon = tech.icon || 'fas fa-code';

        // Determine skill level class for color
        let levelClass = 'intermediate';
        if (level >= 80) levelClass = 'expert';
        else if (level >= 60) levelClass = 'advanced';

        const item = document.createElement('div');
        item.className = 'skill-bar-item';
        item.innerHTML = `
            <div class="skill-bar-header">
                <span class="skill-bar-name"><i class="${icon}"></i> ${tech.name}</span>
                <span class="skill-bar-percent">${level}%</span>
            </div>
            <div class="skill-bar-track">
                <div class="skill-bar-fill" data-level="${levelClass}" data-level-percent="${level}" style="width: 0%; background: ${color};"></div>
            </div>
        `;

        div.appendChild(item);
    });

    container.appendChild(div);

    // Trigger skill bar animation
    setTimeout(() => {
        animateSkillBars(container);
    }, 100);
}

/**
 * Animate skill bars within a container
 */
function animateSkillBars(container) {
    const bars = container.querySelectorAll('.skill-bar-fill');

    // Use Intersection Observer for scroll-triggered animation
    const observer = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
            if (entry.isIntersecting) {
                bars.forEach((bar, index) => {
                    setTimeout(() => {
                        const level = bar.getAttribute('data-level-percent') || '0';
                        bar.style.width = level + '%';
                        bar.classList.add('animate');
                    }, index * 100);
                });
                observer.disconnect();
            }
        });
    }, {
        threshold: 0.2,
        rootMargin: '0px 0px -50px 0px'
    });

    observer.observe(container);
}

// Initialize on DOM ready
document.addEventListener('DOMContentLoaded', () => {
    loadAboutData();
});

/**
 * Calculate tech count with rounding logic
 * Count: showInStats=true && !isHidden && !hasExperience
 * Rounding: 42→40, 39→30, 8→8 (if <=11), 20→20 (if divisible by 10)
 */
function calculateTechCount() {
    if (!technologiesData) return { count: 0, displayValue: 0 };

    // Count technologies matching criteria
    const matchingTechs = Object.values(technologiesData).filter(tech => {
        const flags = tech.flags || {};
        return flags.showInStats === true &&
            !flags.isHidden &&
            !flags.hasExperience;
    });

    const count = matchingTechs.length;

    // Apply rounding logic
    let displayValue;
    if (count <= 11) {
        // Small numbers: keep as is
        displayValue = count;
    } else if (count % 10 === 0) {
        // Divisible by 10: keep as is
        displayValue = count;
    } else {
        // Round down to nearest 10
        displayValue = Math.floor(count / 10) * 10;
    }

    return { count, displayValue };
}

/**
 * Render tech counter with calculated value
 */
function renderTechCounter() {
    const counter = document.getElementById('techCounter');
    if (!counter) return;

    const { displayValue } = calculateTechCount();
    const numberEl = counter.querySelector('.stat-number');

    if (numberEl) {
        numberEl.setAttribute('data-target', displayValue);
        numberEl.textContent = '0';
    }

    // Trigger counter animation
    setTimeout(() => {
        animateCounter(numberEl, displayValue);
    }, 500);
}

/**
 * Calculate languages count
 * Count: isProgrammingLanguage=true && !isHidden && !hasExperience
 * Includes learning languages (isLearning=true but hasExperience=false)
 * Returns exact count (no rounding)
 */
function calculateLanguagesCount() {
    if (!technologiesData) return 0;

    return Object.values(technologiesData).filter(tech => {
        const flags = tech.flags || {};
        return flags.isProgrammingLanguage === true &&
            !flags.isHidden &&
            !flags.hasExperience;
    }).length;
}


/**
 * Get skill level label based on level value
 * Uses settings.skillLevels from technologies.json
 */
function getSkillLevelLabel(level) {
    if (!technologiesData || !technologiesData.settings || !technologiesData.settings.skillLevels) {
        return '';
    }

    const levels = technologiesData.settings.skillLevels;

    if (level >= levels.expert.min) return levels.expert.label;
    if (level >= levels.advanced.min) return levels.advanced.label;
    if (level >= levels.intermediate.min) return levels.intermediate.label;
    return levels.beginner.label;
}

/**
 * Calculate total experience years from experience.json
 * Rounds to nearest year: >=6 months rounds up, <6 months rounds down
 * Returns {years, suffix} where suffix is '+' or '-' based on rounding direction
 */
async function calculateExperienceYears() {
    try {
        const basePath = getBasePath();
        const expUrl = `${basePath}/_data/experience.json`;
        const response = await fetch(expUrl);
        if (!response.ok) {
            throw new Error('Failed to load experience.json');
        }
        const expData = await response.json();

        const useManualTotal = expData.useManualTotal || false;
        const manualTotal = expData.manualTotal || '';

        if (useManualTotal && manualTotal) {
            // Extract number from manual total (e.g., "2 года" -> 2)
            const match = manualTotal.match(/(\d+)/);
            const years = match ? parseInt(match[1]) : 2;
            return { years, suffix: '' };
        }

        // Merge intervals algorithm (no overlap counting) - синхронизировано с experience.html
        const now = new Date();
        const currentYear = now.getFullYear();
        const currentMonth = now.getMonth() + 1;

        // Convert to intervals [start, end]
        let intervals = expData.experience.map(exp => {
            const start = exp.period.start.split('-').map(Number);
            const end = exp.period.isCurrent
                ? [currentYear, currentMonth]
                : exp.period.end.split('-').map(Number);
            return { start, end };
        });

        // Sort by start date
        intervals.sort((a, b) => (a.start[0] - b.start[0]) * 12 + (a.start[1] - b.start[1]));

        // Merge overlapping intervals
        let merged = [];
        for (let interval of intervals) {
            if (merged.length === 0 || merged[merged.length - 1].end[0] * 12 + merged[merged.length - 1].end[1] < interval.start[0] * 12 + interval.start[1]) {
                merged.push(interval);
            } else {
                // Extend end date to max of both intervals
                const currentEndMonths = merged[merged.length - 1].end[0] * 12 + merged[merged.length - 1].end[1];
                const newEndMonths = interval.end[0] * 12 + interval.end[1];
                if (newEndMonths > currentEndMonths) {
                    const newEndTotalMonths = newEndMonths;
                    merged[merged.length - 1].end[0] = Math.floor(newEndTotalMonths / 12);
                    merged[merged.length - 1].end[1] = (newEndTotalMonths % 12) || 12;
                }
            }
        }

        // Calculate total months from merged intervals
        let totalMonths = 0;
        merged.forEach(({ start, end }) => {
            totalMonths += (end[0] - start[0]) * 12 + (end[1] - start[1]);
        });

        const years = Math.floor(totalMonths / 12);
        const remainingMonths = totalMonths % 12;

        // Округление для счётчика (как было)
        let displayYears;
        let suffix;
        if (remainingMonths >= 6) {
            displayYears = years + 1;
            suffix = '~-';
        } else {
            displayYears = years;
            suffix = '~+';
        }

        return { years: displayYears, suffix };

    } catch (error) {
        console.error('About: failed to calculate experience', error);
        return { years: 2, suffix: '+' }; // fallback
    }
}

/**
 * Render experience counter with calculated value
 */
async function renderExperienceCounter() {
    const counter = document.getElementById('experienceCounter');
    if (!counter) return;

    const { years, suffix } = await calculateExperienceYears();
    const numberEl = counter.querySelector('.stat-number');
    const suffixEl = counter.querySelector('.stat-suffix');

    if (numberEl) {
        numberEl.setAttribute('data-target', years);
        numberEl.textContent = '0';
    }

    // Update suffix based on rounding direction
    if (suffixEl) {
        suffixEl.textContent = suffix;
    }

    // Trigger counter animation
    setTimeout(() => {
        animateCounter(numberEl, years);
    }, 700);
}

/**
 * Render languages counter with exact value
 */
function renderLanguagesCounter() {
    const counter = document.getElementById('languagesCounter');
    if (!counter) return;

    const count = calculateLanguagesCount();
    const numberEl = counter.querySelector('.stat-number');

    if (numberEl) {
        numberEl.setAttribute('data-target', count);
        numberEl.textContent = '0';
    }

    // Trigger counter animation
    setTimeout(() => {
        animateCounter(numberEl, count);
    }, 600);
}


/**
 * Render counter labels from about.json
 */
function renderCounterLabels() {
    if (!aboutData || !aboutData.stats) return;

    const stats = aboutData.stats;

    // Tech label
    const techLabel = document.getElementById('techLabel');
    if (techLabel && stats.tech && stats.tech.label) {
        techLabel.textContent = stats.tech.label;
    }

    // Languages label
    const languagesLabel = document.getElementById('languagesLabel');
    if (languagesLabel && stats.languages && stats.languages.label) {
        languagesLabel.textContent = stats.languages.label;
    }

    // Experience label
    const experienceLabel = document.getElementById('experienceLabel');
    if (experienceLabel && stats.experience && stats.experience.label) {
        experienceLabel.textContent = stats.experience.label;
    }

    // Projects label
    const projectsLabel = document.getElementById('projectsLabel');
    if (projectsLabel && stats.projects && stats.projects.label) {
        projectsLabel.textContent = stats.projects.label;
    }
}

/**
 * Render projects counter with calculated value from projects.json
 */
function renderProjectsCounter() {

    const counter = document.querySelector('.stat-item[data-stat="projects"]');
    if (!counter) return;

    // Count projects from projects.json (excluding hiddenProject)
    const count = aboutProjectsData?.projects?.length || 0;

    const numberEl = counter.querySelector('.stat-number');

    if (numberEl) {
        numberEl.setAttribute('data-target', count);
        numberEl.textContent = '0';
    }

    // Trigger counter animation
    setTimeout(() => {
        animateCounter(numberEl, count);
    }, 800);
}

/**
 * Animate counter from 0 to target
 */
function animateCounter(element, target) {

    if (!element) return;

    const duration = 1500;
    const startTime = performance.now();

    function update(currentTime) {
        const elapsed = currentTime - startTime;
        const progress = Math.min(elapsed / duration, 1);

        // Ease out
        const easeOut = 1 - Math.pow(1 - progress, 3);
        const current = Math.floor(target * easeOut);

        element.textContent = current;

        if (progress < 1) {
            requestAnimationFrame(update);
        } else {
            element.textContent = target;
        }
    }

    requestAnimationFrame(update);
}

// Export for potential use
window.loadAboutData = loadAboutData;


// === tech-modal.js ===
// Tech Modal functionality - global version

let techData = null;
let projectsData = null;
let experienceData = null;

/**
 * Load all data from JSON files
 */
async function loadAllData() {
    try {
        // Get base path for GitHub Pages compatibility
        const basePath = window.location.pathname.includes('/skywireneo.github.io')
            ? '/skywireneo.github.io'
            : '';

        // Load technologies
        const techUrl = `${basePath}/_data/technologies.json`;
        const techResponse = await fetch(techUrl);
        if (techResponse.ok) {
            const techJson = await techResponse.json();
            techData = {};
            techJson.technologies.forEach(tech => {
                techData[tech.id] = tech;
            });
            // Export for other scripts
            window.techData = techData;
        }

        // Load projects
        const projectsUrl = `${basePath}/_data/projects.json`;
        const projectsResponse = await fetch(projectsUrl);
        if (projectsResponse.ok) {
            projectsData = await projectsResponse.json();
        }

        // Load experience
        const experienceUrl = `${basePath}/_data/experience.json`;
        const experienceResponse = await fetch(experienceUrl);
        if (experienceResponse.ok) {
            experienceData = await experienceResponse.json();
        }
    } catch (error) {
        console.error('Tech Modal: failed to load data', error);
    }
}

/**
 * Get project title by ID
 */
function getProjectTitle(projectId) {
    if (!projectsData) return null;

    // Check visible projects
    if (projectsData.projects) {
        const project = projectsData.projects.find(p => p.id === projectId);
        if (project) return project.title;
    }

    // Check hidden project
    if (projectsData.hiddenProject && projectsData.hiddenProject.id === projectId) {
        return projectsData.hiddenProject.title;
    }

    return null;
}

/**
 * Get experience company by ID
 */
function getExperienceCompany(expId) {
    if (!experienceData || !experienceData.experience) return null;

    const exp = experienceData.experience.find(e => e.id === expId);
    if (exp) return exp.company;

    return null;
}

function openTechModal(techId) {
    const techModal = document.getElementById('techModal');

    if (!techData || !techData[techId]) {
        console.warn('Tech Modal: no data for techId', techId);
        return;
    }

    const tech = techData[techId];
    const details = tech.details || {};
    const flags = tech.flags || {};

    // Update modal title
    const titleEl = document.getElementById('techModalTitle');
    if (titleEl) {
        // Clear existing content
        titleEl.innerHTML = '';

        // Create title wrapper
        const titleWrapper = document.createElement('div');
        titleWrapper.className = 'tech-title-wrapper';

        // Add icon if exists
        if (tech.icon) {
            const iconEl = document.createElement('i');
            iconEl.className = tech.icon;
            iconEl.style.marginRight = '0.5rem';
            iconEl.style.color = tech.color || 'var(--accent)';
            titleWrapper.appendChild(iconEl);
        }

        // Create title text
        const titleText = document.createElement('span');
        titleText.textContent = tech.name;
        titleWrapper.appendChild(titleText);

        // Add status badge
        if (flags.hasExperience) {
            const statusBadge = document.createElement('div');
            statusBadge.className = 'tech-status-badge status-past';
            statusBadge.innerHTML = '<i class="fas fa-history"></i> Сейчас активно не использую';
            titleWrapper.appendChild(statusBadge);
        } else if (flags.isLearning) {
            const statusBadge = document.createElement('div');
            statusBadge.className = 'tech-status-badge status-learning';
            statusBadge.innerHTML = '<i class="fas fa-graduation-cap"></i> В процессе изучения';
            titleWrapper.appendChild(statusBadge);
        }

        titleEl.appendChild(titleWrapper);

        // Add years BELOW title wrapper
        if (details.years) {
            const yearsDiv = document.createElement('div');
            yearsDiv.className = 'tech-years-info';
            const hasRange = details.years.includes('-');
            const yearsText = hasRange ? 'Период использования' : 'Использую с';
            const yearsAfterText = hasRange ? 'год' : 'года';
            yearsDiv.innerHTML = `<i class="fas fa-calendar-alt"></i> ${yearsText}: <strong>${details.years} ${yearsAfterText}</strong>`;
            titleEl.appendChild(yearsDiv);
        }
    }

    // Update level if exists (skip if showLevel: false)
    const percentEl = document.getElementById('techModalPercent');
    const progressEl = document.getElementById('techModalProgress');
    const levelSection = document.querySelector('.tech-modal-progress');
    const showLevel = flags.showLevel !== false;

    if (showLevel && percentEl && details.level !== undefined && details.level !== null) {
        percentEl.textContent = details.level + '%';
    }
    if (showLevel && progressEl && details.level !== undefined && details.level !== null) {
        progressEl.style.width = details.level + '%';
    }
    // Hide level section if showLevel is false
    if (levelSection) {
        levelSection.style.display = showLevel ? 'block' : 'none';
    }

    // Update description - use from JSON
    const descEl = document.getElementById('techModalDescription');
    if (descEl) {
        // Clear any previous category descriptions
        const existingCategoryDescs = descEl.parentNode.querySelectorAll('.tech-category-description');
        existingCategoryDescs.forEach(el => el.remove());

        descEl.textContent = details.description || 'Описание технологии...';

        // Add learning description below main description for learning techs
        if (flags.isLearning && flags.learningDescription) {
            const learningDescEl = document.createElement('div');
            learningDescEl.className = 'tech-learning-description';
            learningDescEl.innerHTML = `
                <div class="learning-desc-label"><i class="fas fa-book-reader"></i> В процессе изучения:</div>
                <div class="learning-desc-text">${flags.learningDescription}</div>
            `;
            descEl.parentNode.insertBefore(learningDescEl, descEl.nextSibling);
        }

        // Add category descriptions if they exist
        if (tech.categoryDescriptions) {
            const categories = tech.categories || [];
            categories.forEach(category => {
                if (tech.categoryDescriptions[category]) {
                    const categoryDescEl = document.createElement('div');
                    categoryDescEl.className = 'tech-category-description';
                    categoryDescEl.innerHTML = `
                        <div class="category-desc-label"><i class="fas fa-folder"></i> Я применяю в "${category}" с целью:</div>
                        <div class="category-desc-text">${tech.categoryDescriptions[category]}</div>
                    `;
                    descEl.parentNode.insertBefore(categoryDescEl, descEl.nextSibling);
                }
            });
        }
    }

    // Update projects list - ALWAYS show if there are projects, regardless of showLevel
    const projectList = document.getElementById('techModalProjectList');
    const projectsSection = document.getElementById('techModalProjects');

    if (projectList) {
        projectList.innerHTML = '';

        const appliedProjects = [];

        // Get projects from usedInProjects
        if (tech.usedInProjects && tech.usedInProjects.length > 0) {
            tech.usedInProjects.forEach(projectId => {
                const title = getProjectTitle(projectId);
                if (title) {
                    appliedProjects.push({ type: 'project', title: title });
                }
            });
        }

        // Get experience from usedInExperience
        if (tech.usedInExperience && tech.usedInExperience.length > 0) {
            tech.usedInExperience.forEach(expId => {
                const company = getExperienceCompany(expId);
                if (company) {
                    appliedProjects.push({ type: 'experience', title: company });
                }
            });
        }


        if (appliedProjects.length > 0) {
            appliedProjects.forEach(item => {
                const li = document.createElement('li');
                if (item.type === 'project') {
                    li.innerHTML = `<i class="fas fa-rocket"></i> ${item.title}`;
                } else {
                    li.innerHTML = `<i class="fas fa-briefcase"></i> ${item.title}`;
                }
                projectList.appendChild(li);
            });
            // Show projects section
            if (projectsSection) {
                projectsSection.style.display = 'block';
            }
        } else {
            // Hide projects section if no projects
            if (projectsSection) {
                projectsSection.style.display = 'none';
            }
        }
    }

    // Show modal with animation
    document.body.classList.add('modal-open');
    techModal.classList.remove('closing');
    techModal.classList.add('active');
}

function closeTechModal() {
    const techModal = document.getElementById('techModal');
    if (!techModal) return;

    techModal.classList.add('closing');

    // Wait for animation to finish before hiding
    setTimeout(() => {
        techModal.classList.remove('active', 'closing');
        document.body.classList.remove('modal-open');

        // Remove any learning description that was added
        const learningDesc = techModal.querySelector('.tech-learning-description');
        if (learningDesc) {
            learningDesc.remove();
        }

        // Remove any category descriptions that were added
        const categoryDescs = techModal.querySelectorAll('.tech-category-description');
        categoryDescs.forEach(el => el.remove());
    }, 300);
}

// Global function to handle tech click
window.openTechModal = openTechModal;
window.closeTechModal = closeTechModal;

// Close handlers
document.addEventListener('DOMContentLoaded', () => {
    const techModal = document.getElementById('techModal');
    const techModalClose = document.getElementById('techModalClose');
    const techModalCloseBtn = document.getElementById('techModalCloseBtn');
    const techTags = document.querySelectorAll('.tech-tag');

    // Close handlers
    if (techModalClose) {
        techModalClose.addEventListener('click', closeTechModal);
    }
    if (techModalCloseBtn) {
        techModalCloseBtn.addEventListener('click', closeTechModal);
    }

    // Close on backdrop click
    if (techModal) {
        techModal.addEventListener('click', (e) => {
            if (e.target === techModal) {
                closeTechModal();
            }
        });
    }

    // Close on Escape key
    document.addEventListener('keydown', (e) => {
        if (e.key === 'Escape' && techModal && techModal.classList.contains('active')) {
            closeTechModal();
        }
    });

    // Add click handlers to tech tags
    techTags.forEach(tag => {
        tag.addEventListener('click', (e) => {
            e.preventDefault();
            e.stopPropagation();
            const techId = tag.getAttribute('data-tech');
            if (techId && techData) {
                openTechModal(techId);
            }
        });

        // Add cursor pointer to indicate clickability
        tag.style.cursor = 'pointer';
    });

    // Load all data
    loadAllData();
});


// === project-filters.js ===
// Project filters functionality
const filterBtns = document.querySelectorAll('.filter-btn');
const projectCards = document.querySelectorAll('.project-card');
const filterModeToggle = document.getElementById('filterModeToggle');
const noProjectsMessage = document.querySelector('.no-projects-message');
let filterMode = 'any'; // 'any' or 'all'


filterBtns.forEach(btn => {
    btn.addEventListener('click', () => {
        const filter = btn.getAttribute('data-filter');

        // Toggle active state
        if (filter === 'all') {
            filterBtns.forEach(b => b.classList.remove('active'));
            btn.classList.add('active');
        } else {
            document.querySelector('[data-filter="all"]').classList.remove('active');
            btn.classList.toggle('active');

            // If no filters active, activate 'all'
            const activeFilters = document.querySelectorAll('.filter-btn.active:not([data-filter="all"])');
            if (activeFilters.length === 0) {
                document.querySelector('[data-filter="all"]').classList.add('active');
            }
        }

        applyFilters();
    });
});

filterModeToggle.addEventListener('click', () => {
    filterMode = filterMode === 'any' ? 'all' : 'any';
    filterModeToggle.textContent = filterMode === 'any' ? 'Хотя бы одна' : 'Все выбранные';
    applyFilters();
});

function applyFilters() {
    const activeFilters = Array.from(document.querySelectorAll('.filter-btn.active:not([data-filter="all"])'))
        .map(btn => btn.getAttribute('data-filter'));

    let visibleCount = 0;

    projectCards.forEach(card => {
        const cardTech = card.getAttribute('data-tech').split(' ');

        if (activeFilters.length === 0) {
            card.classList.remove('hidden');
            visibleCount++;
            return;
        }

        let shouldShow = false;

        if (filterMode === 'any') {
            // Show if card has at least one of the selected technologies
            shouldShow = activeFilters.some(filter => cardTech.includes(filter));
        } else {
            // Show if card has all of the selected technologies
            shouldShow = activeFilters.every(filter => cardTech.includes(filter));
        }

        if (shouldShow) {
            card.classList.remove('hidden');
            visibleCount++;
        } else {
            card.classList.add('hidden');
        }
    });

    // Show/hide "no projects found" message
    if (noProjectsMessage) {
        if (visibleCount === 0) {
            noProjectsMessage.style.display = 'block';
        } else {
            noProjectsMessage.style.display = 'none';
        }
    }
}


// === skill-bars.js ===
/* ============================================
   SKILL BARS ANIMATION
   ============================================ */

class SkillBarsAnimation {
    constructor() {
        this.skillBars = document.querySelectorAll('.skill-bar-fill');
        this.animated = false;
        this.init();
    }

    init() {
        if (this.skillBars.length === 0) return;

        // Use Intersection Observer for scroll-triggered animation
        const observer = new IntersectionObserver((entries) => {
            entries.forEach(entry => {
                if (entry.isIntersecting && !this.animated) {
                    this.animate();
                    this.animated = true;
                }
            });
        }, {
            threshold: 0.2,
            rootMargin: '0px 0px -50px 0px'
        });

        // Observe the first skill bar container
        const container = this.skillBars[0].closest('.skill-bar-container');
        if (container) {
            observer.observe(container);
        }
    }

    animate() {
        this.skillBars.forEach((bar, index) => {
            // Staggered animation
            setTimeout(() => {
                const level = bar.getAttribute('data-level-percent') || '0';
                bar.style.width = level + '%';
                bar.classList.add('animate');
            }, index * 100); // 100ms delay between each
        });
    }
}

// Initialize when DOM is ready
document.addEventListener('DOMContentLoaded', () => {
    new SkillBarsAnimation();
});


// === faq.js ===
// FAQ with Section Switcher - Split View + Full-Text Search
let faqConfig = null;
let sectionLabels = {};
let searchSynonyms = {};

document.addEventListener('DOMContentLoaded', async () => {
    await loadFaqConfig();
    initFaqSwitcher();
    initFaqQuestions();
    initFaqSearch();
    initScrollableQuestions();
    addSectionLabels();
});

/**
 * Load FAQ configuration from JSON
 */
async function loadFaqConfig() {
    try {
        const basePath = window.location.pathname.includes('/skywireneo.github.io')
            ? '/skywireneo.github.io'
            : '';
        const response = await fetch(`${basePath}/_data/faq.json`);
        if (response.ok) {
            faqConfig = await response.json();

            // Build sectionLabels from config
            faqConfig.sections.forEach(section => {
                sectionLabels[section.id] = {
                    icon: section.icon,
                    text: section.title,
                    short: section.shortTitle
                };
            });

            // Get searchSynonyms from config
            searchSynonyms = faqConfig.searchSynonyms || {};

        } else {
            console.error('FAQ: failed to load config');
        }
    } catch (error) {
        console.error('FAQ: failed to load config', error);
    }
}

// Add section labels to questions
function addSectionLabels() {
    if (!faqConfig) return;

    faqConfig.sections.forEach(section => {
        const tabContent = document.getElementById(`faq-${section.id}`);
        if (!tabContent) return;

        const questions = tabContent.querySelectorAll('.faq-question');
        const sectionInfo = sectionLabels[section.id];

        questions.forEach(question => {
            // Add section data attribute
            question.setAttribute('data-section', section.id);
            question.setAttribute('data-section-name', sectionInfo ? sectionInfo.short : '');
        });
    });
}


// Initialize section switcher buttons
function initFaqSwitcher() {
    const switchButtons = document.querySelectorAll('.faq-switch-btn');
    const contents = document.querySelectorAll('.faq-tab-content');
    const currentSectionLabel = document.getElementById('faqCurrentSection');

    switchButtons.forEach(btn => {
        btn.addEventListener('click', () => {
            const targetTab = btn.getAttribute('data-tab');

            // Hide all contents
            contents.forEach(content => {
                content.classList.remove('active');
            });

            // Show target content
            const targetContent = document.getElementById(`faq-${targetTab}`);
            if (targetContent) {
                targetContent.classList.add('active');
            }

            // Update current section label
            if (currentSectionLabel && sectionLabels[targetTab]) {
                const label = sectionLabels[targetTab];
                currentSectionLabel.innerHTML = `<i class="fas ${label.icon}"></i> ${label.text}`;
            }

            // Reset search when switching tabs
            resetFaqSearch();

            // Re-initialize scroll detection for new tab
            setTimeout(initScrollableQuestions, 100);
        });
    });
}

// Initialize question/answer switching within each tab
function initFaqQuestions() {
    const tabContents = document.querySelectorAll('.faq-tab-content');

    tabContents.forEach(content => {
        const questions = content.querySelectorAll('.faq-question');
        const answers = content.querySelectorAll('.faq-answer-content');

        // Show first answer by default for each tab
        if (questions.length > 0 && answers.length > 0) {
            questions[0].classList.add('active');
            answers[0].classList.add('active');
        }

        questions.forEach(question => {
            question.addEventListener('click', () => {
                const answerId = question.getAttribute('data-answer');

                // Remove active from all questions in this tab
                questions.forEach(q => q.classList.remove('active'));

                // Add active to clicked question
                question.classList.add('active');

                // Hide all answers in this tab
                answers.forEach(answer => {
                    answer.classList.remove('active');
                });

                // Show corresponding answer
                const targetAnswer = content.querySelector(`#faq-answer-${answerId}`);
                if (targetAnswer) {
                    targetAnswer.classList.add('active');
                }
            });
        });
    });
}

// ============================================
// FAQ FULL-TEXT SEARCH ACROSS ALL SECTIONS
// ============================================

// Search synonyms loaded from JSON (faqConfig.searchSynonyms)


function initFaqSearch() {
    const searchInput = document.getElementById('faqSearchInput');
    const searchClear = document.getElementById('faqSearchClear');
    const searchResults = document.getElementById('faqSearchResults');

    if (!searchInput) return;

    // Search on input
    searchInput.addEventListener('input', (e) => {
        const query = e.target.value.trim().toLowerCase();

        // Show/hide clear button
        if (searchClear) {
            searchClear.style.display = query.length > 0 ? 'flex' : 'none';
        }

        if (query.length > 0) {
            performFaqSearch(query);
        } else {
            resetFaqSearch();
        }
    });

    // Clear search
    if (searchClear) {
        searchClear.addEventListener('click', () => {
            searchInput.value = '';
            searchClear.style.display = 'none';
            resetFaqSearch();
            searchInput.focus();
        });
    }

    // Keyboard shortcuts
    document.addEventListener('keydown', (e) => {
        // Ctrl/Cmd + F to focus search
        if ((e.ctrlKey || e.metaKey) && e.key === 'f') {
            const faqSection = document.getElementById('faq');
            if (faqSection && isElementInViewport(faqSection)) {
                e.preventDefault();
                searchInput.focus();
            }
        }

        // Escape to clear search
        if (e.key === 'Escape' && document.activeElement === searchInput) {
            searchInput.value = '';
            resetFaqSearch();
            searchInput.blur();
        }
    });
}

function isElementInViewport(el) {
    const rect = el.getBoundingClientRect();
    return rect.top < window.innerHeight && rect.bottom > 0;
}

function performFaqSearch(query) {
    const allQuestions = document.querySelectorAll('.faq-question');
    const searchResults = document.getElementById('faqSearchResults');
    const activeTab = document.querySelector('.faq-tab-content.active');

    if (!query) {
        resetFaqSearch();
        return;
    }

    // Expand search query with synonyms
    const expandedQuery = expandSearchQuery(query);
    const searchTerms = expandedQuery.split(/\s+/).filter(term => term.length > 0);

    let matches = [];
    let bestMatch = null;
    let bestScore = 0;

    allQuestions.forEach(question => {
        const questionText = question.textContent.toLowerCase();
        const searchKeywords = (question.getAttribute('data-search') || '').toLowerCase();
        const answerId = question.getAttribute('data-answer');
        const answerContent = document.querySelector(`#faq-answer-${answerId}`);
        const answerText = answerContent ? answerContent.textContent.toLowerCase() : '';
        const sectionName = (question.getAttribute('data-section-name') || '').toLowerCase();

        // Calculate relevance score
        let score = 0;
        let matchedTerms = [];

        searchTerms.forEach(term => {
            // Exact match in question text (highest priority)
            if (questionText.includes(term)) {
                score += 10;
                if (questionText.indexOf(term) < 20) score += 5; // Bonus for match at start
                matchedTerms.push(term);
            }
            // Match in keywords
            else if (searchKeywords.includes(term)) {
                score += 8;
                matchedTerms.push(term);
            }
            // Match in answer text
            else if (answerText.includes(term)) {
                score += 5;
                matchedTerms.push(term);
            }
            // Match in section name
            else if (sectionName.includes(term)) {
                score += 2;
                matchedTerms.push(term);
            }
        });

        if (score > 0) {
            matches.push({
                question: question,
                score: score,
                matchedTerms: [...new Set(matchedTerms)]
            });

            if (score > bestScore) {
                bestScore = score;
                bestMatch = question;
            }
        }
    });

    // Sort matches by score
    matches.sort((a, b) => b.score - a.score);

    // Update UI
    updateSearchResults(matches, bestMatch, searchResults, query);
}

function expandSearchQuery(query) {
    let expanded = query;
    const words = query.split(/\s+/);

    words.forEach(word => {
        // Check if word has synonyms
        for (const [key, synonyms] of Object.entries(searchSynonyms)) {
            if (word.includes(key) || synonyms.some(s => word.includes(s))) {
                // Add all synonyms to search
                expanded += ' ' + synonyms.join(' ');
            }
        }
    });

    return expanded;
}

function updateSearchResults(matches, bestMatch, searchResultsElement, query) {
    const allQuestions = document.querySelectorAll('.faq-question');
    const activeTab = document.querySelector('.faq-tab-content.active');

    // Hide all questions first
    allQuestions.forEach(q => {
        q.classList.add('hidden');
        // Remove section label if exists
        const existingLabel = q.querySelector('.faq-section-badge');
        if (existingLabel) {
            existingLabel.remove();
        }
        // Reset text
        q.childNodes.forEach(node => {
            if (node.nodeType === Node.TEXT_NODE) {
                node.textContent = node.textContent.replace(/\s*\([^)]+\)\s*$/, '');
            }
        });
    });

    if (matches.length === 0) {
        // No results
        if (searchResultsElement) {
            searchResultsElement.textContent = 'Ничего не найдено';
            searchResultsElement.style.color = 'var(--error, #ef4444)';
        }
        return;
    }

    // Show matched questions with section labels
    const visibleMatches = matches.slice(0, 15); // Limit to top 15 results

    visibleMatches.forEach(match => {
        const question = match.question;
        const sectionName = question.getAttribute('data-section-name');

        // Remove hidden class
        question.classList.remove('hidden');

        // Add section badge
        const badge = document.createElement('span');
        badge.className = 'faq-section-badge';
        badge.textContent = ` (${sectionName})`;
        badge.style.cssText = `
            color: var(--accent);
            font-size: 0.8em;
            opacity: 0.8;
            margin-left: 0.5rem;
            font-weight: 500;
        `;
        question.appendChild(badge);

        // Highlight matching text
        highlightMatches(question, match.matchedTerms);
    });

    // Update results counter
    if (searchResultsElement) {
        searchResultsElement.textContent = `Найдено: ${matches.length}`;
        searchResultsElement.style.color = 'var(--accent)';
    }

    // Auto-select best match
    if (bestMatch && activeTab) {
        // Check if best match is in active tab
        const bestMatchTab = bestMatch.closest('.faq-tab-content');
        if (bestMatchTab && bestMatchTab !== activeTab) {
            // Switch to the tab containing best match
            const tabId = bestMatchTab.id.replace('faq-', '');
            const switchBtn = document.querySelector(`.faq-switch-btn[data-tab="${tabId}"]`);
            if (switchBtn) {
                switchBtn.click();
            }
        }

        // Click the best match after a short delay
        setTimeout(() => {
            bestMatch.click();
            bestMatch.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }, 100);
    }

    // Update scroll indicators
    setTimeout(updateScrollIndicators, 50);
}

function highlightMatches(element, terms) {
    if (!terms || terms.length === 0) return;

    // Get text content excluding the badge
    const badge = element.querySelector('.faq-section-badge');
    const badgeText = badge ? badge.textContent : '';
    const originalText = element.textContent.replace(badgeText, '').trim();

    // Create regex for all terms
    const regex = new RegExp(`(${terms.map(escapeRegex).join('|')})`, 'gi');

    // Replace text with highlighted version
    const highlightedText = originalText.replace(regex, '<mark class="faq-search-highlight">$1</mark>');

    // Update element HTML
    element.innerHTML = highlightedText;
    if (badge) {
        element.appendChild(badge);
    }
}

function resetFaqSearch() {
    const allQuestions = document.querySelectorAll('.faq-question');
    const searchResults = document.getElementById('faqSearchResults');
    const activeTab = document.querySelector('.faq-tab-content.active');

    allQuestions.forEach(question => {
        question.classList.remove('hidden');

        // Remove section badge
        const badge = question.querySelector('.faq-section-badge');
        if (badge) {
            badge.remove();
        }

        // Reset to original text
        const originalText = question.textContent.replace(/\s*\([^)]+\)\s*$/, '');
        question.textContent = originalText;
    });

    if (searchResults) {
        searchResults.textContent = '';
    }

    // Reset to first question in active tab
    if (activeTab) {
        const firstQuestion = activeTab.querySelector('.faq-question');
        if (firstQuestion) {
            firstQuestion.click();
        }
    }

    // Update scroll indicators
    setTimeout(updateScrollIndicators, 50);
}

function escapeRegex(string) {
    return string.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

// ============================================
// SCROLLABLE QUESTIONS WITH FADE EFFECTS
// ============================================

function initScrollableQuestions() {
    const scrollableContainers = document.querySelectorAll('.faq-questions-scrollable');

    scrollableContainers.forEach(container => {
        // Initial check
        updateScrollIndicators();

        // Listen for scroll
        container.addEventListener('scroll', () => {
            updateScrollIndicators();
        });
    });

    // Listen for resize
    window.addEventListener('resize', () => {
        updateScrollIndicators();
    });
}

function updateScrollIndicators() {
    const scrollableContainers = document.querySelectorAll('.faq-questions-scrollable');

    scrollableContainers.forEach(container => {
        const scrollTop = container.scrollTop;
        const scrollHeight = container.scrollHeight;
        const clientHeight = container.clientHeight;

        // Check if can scroll up
        if (scrollTop > 10) {
            container.classList.add('can-scroll-up');
        } else {
            container.classList.remove('can-scroll-up');
        }

        // Check if can scroll down
        if (scrollTop + clientHeight < scrollHeight - 10) {
            container.classList.add('can-scroll-down');
        } else {
            container.classList.remove('can-scroll-down');
        }
    });
}


// === lightbox.js ===
// Lightbox carousel functionality
const lightbox = document.getElementById('lightbox');
const lightboxImg = document.getElementById('lightboxImg');
const lightboxCounter = document.getElementById('lightboxCounter');
const lightboxProjectName = document.getElementById('lightboxProjectName');
const lightboxImageTitle = document.getElementById('lightboxImageTitle');
const lightboxThumbnails = document.getElementById('lightboxThumbnails');
const lightboxClose = document.getElementById('lightboxClose');
const prevBtn = document.getElementById('prevBtn');
const nextBtn = document.getElementById('nextBtn');

let images = [];
let currentIndex = 0;
let currentProjectName = '';

// Initialize lightbox for all project images
document.querySelectorAll('.project-card').forEach(card => {
    const projectTitle = card.querySelector('h3').textContent;
    const imgs = Array.from(card.querySelectorAll('.project-images img'));

    imgs.forEach((img, idx) => {
        img.addEventListener('click', () => {
            images = imgs;
            currentIndex = idx;
            currentProjectName = projectTitle;
            showLightbox();
        });
    });
});

function showLightbox() {
    updateLightbox();
    lightbox.style.display = 'flex';

    // Trigger reflow to ensure animation plays
    void lightbox.offsetWidth;

    // Add opening class for animation
    lightbox.classList.add('opening');
    document.body.classList.add('modal-open');
    document.body.classList.add('lightbox-open');
}



function updateLightbox() {
    const currentImg = images[currentIndex];
    lightboxImg.src = currentImg.src;
    lightboxCounter.textContent = `${currentIndex + 1} / ${images.length}`;
    lightboxProjectName.textContent = currentProjectName;

    const title = currentImg.getAttribute('data-title') || currentImg.alt;
    const desc = currentImg.getAttribute('data-desc') || '';
    lightboxImageTitle.textContent = desc ? `${title} — ${desc}` : title;

    updateThumbnails();
}

function updateThumbnails() {
    lightboxThumbnails.innerHTML = '';
    images.forEach((img, idx) => {
        const thumb = document.createElement('img');
        thumb.src = img.src;
        thumb.className = 'lightbox-thumb';
        thumb.title = img.getAttribute('data-title') || img.alt;
        if (idx === currentIndex) {
            thumb.classList.add('active');
        }
        thumb.addEventListener('click', () => {
            currentIndex = idx;
            updateLightbox();
        });
        lightboxThumbnails.appendChild(thumb);
    });

    // Scroll to active thumbnail
    const activeThumb = lightboxThumbnails.querySelector('.active');
    if (activeThumb) {
        activeThumb.scrollIntoView({ behavior: 'smooth', inline: 'center', block: 'nearest' });
    }
}

function changeImage(step) {
    currentIndex = (currentIndex + step + images.length) % images.length;
    updateLightbox();
}



function closeLightbox() {
    // Add closing class for animation
    lightbox.classList.remove('opening');
    lightbox.classList.add('closing');

    // Wait for animation to finish before hiding
    setTimeout(() => {
        lightbox.style.display = 'none';
        lightbox.classList.remove('closing');
        document.body.classList.remove('modal-open');
        document.body.classList.remove('lightbox-open');
    }, 400);
}



// Event listeners
prevBtn.addEventListener('click', (e) => {
    e.stopPropagation();
    changeImage(-1);
});

nextBtn.addEventListener('click', (e) => {
    e.stopPropagation();
    changeImage(1);
});

lightboxClose.addEventListener('click', closeLightbox);

// Close on background click
lightbox.addEventListener('click', (e) => {
    if (e.target === lightbox || e.target.classList.contains('lightbox-main')) {
        closeLightbox();
    }
});

// Close on Escape key
document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && lightbox.style.display === 'flex') {
        closeLightbox();
    }
});


// === time-widget.js ===
/**
 * Time Status Widget - Button and modal for availability status
 */

(function () {
    'use strict';

    // Configuration loaded from JSON
    let CONFIG = null;
    let timeStatusData = null;

    // Test mode - forced status (null = auto, 'online', 'offline')
    let forcedStatus = null;

    /**
     * Get base path for GitHub Pages compatibility
     */
    function getBasePath() {
        return window.location.pathname.includes('/skywireneo.github.io')
            ? '/skywireneo.github.io'
            : '';
    }

    /**
     * Load time status configuration from JSON
     */
    async function loadTimeStatusConfig() {
        try {
            const basePath = getBasePath();
            const url = `${basePath}/_data/time-status.json`;
            const response = await fetch(url);
            if (!response.ok) {
                throw new Error('Failed to load time-status.json');
            }
            timeStatusData = await response.json();

            // Set CONFIG from loaded data with fallbacks
            CONFIG = {
                workStart: timeStatusData.settings?.workStart ?? 10,
                workEnd: timeStatusData.settings?.workEnd ?? 19,
                timeZone: timeStatusData.settings?.timeZone ?? 'Europe/Moscow',
                updateInterval: timeStatusData.settings?.updateInterval ?? 60000
            };
        } catch (error) {
            console.error('TimeWidget: failed to load config, using defaults', error);
            // Fallback defaults
            CONFIG = {
                workStart: 10,
                workEnd: 19,
                timeZone: 'Europe/Moscow',
                updateInterval: 60000
            };
        }
    }

    // DOM Elements
    let statusToggle, statusIcon, statusText;
    let timeStatusModal, timeStatusModalClose, timeStatusModalCloseBtn;
    let modalCurrentTime, modalAvailabilityStatus, modalScheduleProgress;

    /**
     * Update static modal content from JSON
     */
    function updateModalStaticContent() {
        if (!timeStatusData || !timeStatusData.labels) return;

        const labels = timeStatusData.labels;

        // Button title (tooltip)
        if (statusToggle && labels.button && labels.button.title) {
            statusToggle.setAttribute('title', labels.button.title);
        }

        // Schedule title
        const scheduleTitle = document.getElementById('scheduleTitle');
        if (scheduleTitle && labels.modal && labels.modal.scheduleTitle) {
            scheduleTitle.textContent = labels.modal.scheduleTitle;
        }

        // Schedule note
        const scheduleNote = document.getElementById('scheduleNote');
        if (scheduleNote && labels.modal && labels.modal.scheduleNote) {
            let noteText = labels.modal.scheduleNote
                .replace('{workStart}', CONFIG.workStart)
                .replace('{workEnd}', CONFIG.workEnd);
            scheduleNote.textContent = noteText;
        }

        // Response time title
        const responseTimeTitle = document.getElementById('responseTimeTitle');
        if (responseTimeTitle && labels.modal && labels.modal.responseTimeTitle) {
            responseTimeTitle.textContent = labels.modal.responseTimeTitle;
        }

        // Response time text
        const responseTimeText = document.getElementById('responseTimeText');
        if (responseTimeText && labels.modal && labels.modal.responseTimeText) {
            responseTimeText.innerHTML = labels.modal.responseTimeText;
        }

        // Response hint
        const responseHint = document.getElementById('responseHint');
        if (responseHint && labels.modal && labels.modal.responseHint) {
            responseHint.textContent = labels.modal.responseHint;
        }

        // Response checklist
        const responseChecklist = document.getElementById('responseChecklist');
        if (responseChecklist && labels.modal && labels.modal.responseChecklist && Array.isArray(labels.modal.responseChecklist)) {
            responseChecklist.innerHTML = labels.modal.responseChecklist
                .map(item => `<li>${item}</li>`)
                .join('');
        }

        // Urgent note
        const urgentNote = document.getElementById('urgentNote');
        if (urgentNote && labels.modal && labels.modal.urgentNote) {
            urgentNote.textContent = labels.modal.urgentNote;
        }

        // Update schedule markers
        const markerStart = document.getElementById('markerStart');
        const markerMiddle = document.getElementById('markerMiddle');
        const markerEnd = document.getElementById('markerEnd');

        if (markerStart) {
            markerStart.textContent = `${CONFIG.workStart}:00`;
        }
        if (markerMiddle) {
            const middleTime = Math.floor((CONFIG.workStart + CONFIG.workEnd) / 2);
            markerMiddle.textContent = `${middleTime}:00`;
        }
        if (markerEnd) {
            markerEnd.textContent = `${CONFIG.workEnd}:00`;
        }
    }



    /**
     * Initialize the time status widget
     */
    async function init() {
        // Load configuration first
        await loadTimeStatusConfig();

        // Button elements
        statusToggle = document.getElementById('statusToggle');
        statusIcon = document.getElementById('statusIcon');
        statusText = document.getElementById('statusText');

        // Modal elements
        timeStatusModal = document.getElementById('timeStatusModal');
        timeStatusModalClose = document.getElementById('timeStatusModalClose');
        timeStatusModalCloseBtn = document.getElementById('timeStatusModalCloseBtn');
        modalCurrentTime = document.getElementById('modalCurrentTime');
        modalAvailabilityStatus = document.getElementById('modalAvailabilityStatus');
        modalScheduleProgress = document.getElementById('modalScheduleProgress');

        if (!statusToggle) {
            console.warn('Status toggle button not found');
            return;
        }

        // Update static modal content from JSON
        updateModalStaticContent();

        // Bind events
        bindEvents();

        // Initial update
        updateStatus();

        // Update every minute
        setInterval(updateStatus, CONFIG.updateInterval);
    }

    /**
     * Bind click events
     */
    function bindEvents() {
        // Open modal on button click
        statusToggle.addEventListener('click', openModal);

        // Close modal handlers
        if (timeStatusModalClose) {
            timeStatusModalClose.addEventListener('click', closeModal);
        }
        if (timeStatusModalCloseBtn) {
            timeStatusModalCloseBtn.addEventListener('click', closeModal);
        }

        // Close on backdrop click
        if (timeStatusModal) {
            timeStatusModal.addEventListener('click', function (e) {
                if (e.target === timeStatusModal) {
                    closeModal();
                }
            });
        }

        // Close on Escape key
        document.addEventListener('keydown', function (e) {
            if (e.key === 'Escape' && timeStatusModal && timeStatusModal.classList.contains('active')) {
                closeModal();
            }
        });
    }

    /**
     * Update button status display
     */
    function updateStatus() {
        const now = new Date();
        const hours = now.getHours();
        const minutes = now.getMinutes();
        const isWeekday = now.getDay() >= 1 && now.getDay() <= 5;

        // Check if online (work hours and weekday) or use forced status
        let isOnline;
        if (forcedStatus === 'online') {
            isOnline = true;
        } else if (forcedStatus === 'offline') {
            isOnline = false;
        } else {
            isOnline = hours >= CONFIG.workStart && hours < CONFIG.workEnd && isWeekday;
        }

        // Update button icon
        if (statusIcon) {
            statusIcon.className = 'fas fa-circle status-icon ' + (isOnline ? 'online' : 'offline');
        }

        // Update button text
        if (statusText) {
            const buttonLabels = timeStatusData?.labels?.button;
            statusText.textContent = isOnline
                ? (buttonLabels?.online ?? 'Онлайн')
                : (buttonLabels?.offline ?? 'Офлайн');
        }

        // Update modal if it's open
        if (timeStatusModal && timeStatusModal.classList.contains('active')) {
            updateModalContent();
        }
    }

    /**
     * Update modal content
     */
    function updateModalContent() {
        const now = new Date();
        const hours = now.getHours();
        const minutes = now.getMinutes();
        const isWeekday = now.getDay() >= 1 && now.getDay() <= 5;

        // Use forced status if set, otherwise calculate from time
        let isOnline;
        if (forcedStatus === 'online') {
            isOnline = true;
        } else if (forcedStatus === 'offline') {
            isOnline = false;
        } else {
            isOnline = hours >= CONFIG.workStart && hours < CONFIG.workEnd && isWeekday;
        }

        // Update time display
        if (modalCurrentTime) {
            const timeString = `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}`;
            modalCurrentTime.textContent = timeString;
        }

        // Update availability status
        if (modalAvailabilityStatus) {
            const statusDot = modalAvailabilityStatus.querySelector('.status-dot');
            const statusText = modalAvailabilityStatus.querySelector('.status-text');

            if (statusDot) {
                statusDot.className = 'status-dot ' + (isOnline ? 'online' : 'offline');
            }
            if (statusText) {
                const modalLabels = timeStatusData?.labels?.modal;
                if (forcedStatus === 'online') {
                    statusText.textContent = modalLabels?.testOnline ?? 'Тест: принудительно онлайн';
                } else if (forcedStatus === 'offline') {
                    statusText.textContent = modalLabels?.testOffline ?? 'Тест: принудительно офлайн';
                } else if (isOnline) {
                    statusText.textContent = modalLabels?.online ?? 'Сейчас на связи';
                } else if (!isWeekday) {
                    statusText.textContent = modalLabels?.weekend ?? 'Выходной — отвечу в понедельник';
                } else if (hours < CONFIG.workStart) {
                    const beforeWorkText = modalLabels?.beforeWork ?? 'Ещё не работаю — начинаю в {time}';
                    statusText.textContent = beforeWorkText.replace('{time}', `${CONFIG.workStart}:00`);
                } else {
                    const afterWorkText = modalLabels?.afterWork ?? 'Уже закончил — до завтра {time}';
                    statusText.textContent = afterWorkText.replace('{time}', `${CONFIG.workStart}:00`);
                }
            }
        }

        // Update schedule progress
        updateScheduleProgress(hours, minutes);
    }

    /**
     * Update the visual schedule progress bar in modal
     */
    function updateScheduleProgress(currentHour, currentMinute) {
        if (!modalScheduleProgress) return;

        const totalMinutes = (CONFIG.workEnd - CONFIG.workStart) * 60;
        const currentMinutes = (currentHour - CONFIG.workStart) * 60 + currentMinute;

        let progressPercent = 0;

        if (currentHour < CONFIG.workStart) {
            progressPercent = 0;
        } else if (currentHour >= CONFIG.workEnd) {
            progressPercent = 100;
        } else {
            progressPercent = (currentMinutes / totalMinutes) * 100;
        }

        modalScheduleProgress.style.width = `${progressPercent}%`;
    }

    /**
     * Open the time status modal
     */
    function openModal() {
        if (!timeStatusModal) return;

        updateModalContent();
        timeStatusModal.classList.add('active');
        timeStatusModal.classList.remove('closing');
        document.body.style.overflow = 'hidden';
    }

    /**
     * Close the time status modal
     */
    function closeModal() {
        if (!timeStatusModal) return;

        timeStatusModal.classList.add('closing');
        timeStatusModal.classList.remove('active');

        setTimeout(() => {
            timeStatusModal.classList.remove('closing');
            document.body.style.overflow = '';
        }, 300);
    }

    // Test control functions
    function setForcedStatus(status) {
        forcedStatus = status;
        updateStatus();
    }

    function getForcedStatus() {
        return forcedStatus;
    }

    // Expose test API globally
    window.TimeStatusTest = {
        setOnline: function () { setForcedStatus('online'); },
        setOffline: function () { setForcedStatus('offline'); },
        setAuto: function () { setForcedStatus(null); },
        getStatus: getForcedStatus
    };

    // Initialize when DOM is ready
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }
})();


// === stats-modal.js ===
/**
 * Stats Modal - Модальные окна для счётчиков статистики
 */

(function () {
    'use strict';

    // Loaded data from JSON
    let aboutData = null;
    let technologiesData = null;
    let skillLevelsSettings = null;
    let experienceData = null;
    let exactExperienceString = '';
    let projectsData = null;





    /**
     * Get base path for GitHub Pages compatibility
     */
    function getBasePath() {
        return window.location.pathname.includes('/skywireneo.github.io')
            ? '/skywireneo.github.io'
            : '';
    }

    /**
     * Load about.json and technologies.json data
     */
    async function loadAboutData() {
        try {
            const basePath = getBasePath();

            // Load about.json
            const aboutUrl = `${basePath}/_data/about.json`;
            const aboutResponse = await fetch(aboutUrl);
            if (!aboutResponse.ok) {
                throw new Error('Failed to load about.json');
            }
            aboutData = await aboutResponse.json();

            // Load technologies.json
            const techUrl = `${basePath}/_data/technologies.json`;
            const techResponse = await fetch(techUrl);
            if (!techResponse.ok) {
                throw new Error('Failed to load technologies.json');
            }
            const techJson = await techResponse.json();
            technologiesData = techJson.technologies || [];
            skillLevelsSettings = techJson.settings?.skillLevels || null;

            // Load experience.json
            const expUrl = `${basePath}/_data/experience.json`;
            const expResponse = await fetch(expUrl);
            if (!expResponse.ok) {
                throw new Error('Failed to load experience.json');
            }
            experienceData = await expResponse.json();

            // Pre-calculate exact experience for modal
            exactExperienceString = calculateExactExperienceSync();

            // Load projects.json
            const projUrl = `${basePath}/_data/projects.json`;
            const projResponse = await fetch(projUrl);
            if (!projResponse.ok) {
                throw new Error('Failed to load projects.json');
            }
            projectsData = await projResponse.json();

        } catch (error) {
            console.error('StatsModal: failed to load data', error);
        }

    }



    /**
     * Generate timeline HTML from stackEvolution data
     */
    function generateTimelineHTML() {
        if (!aboutData || !aboutData.stackEvolution) {
            return '<div class="stats-timeline"><div class="timeline-item"><div class="timeline-desc">Данные загружаются...</div></div></div>';
        }

        const items = aboutData.stackEvolution.map(item => `
            <div class="timeline-item">
                <div class="timeline-year">${item.year}</div>
                <div class="timeline-title">${item.title}</div>
                <div class="timeline-desc">${item.description}</div>
            </div>
        `).join('');

        return `<div class="stats-timeline">${items}</div>`;
    }

    /**
     * Get tech stat data from about.json
     */
    function getTechStatData() {
        if (!aboutData || !aboutData.stats || !aboutData.stats.tech) {
            return {
                title: 'Эволюция стека',
                icon: 'fa-layer-group',
                description: 'Загрузка данных...',
                content: '<div class="stats-timeline"><div class="timeline-item"><div class="timeline-desc">Загрузка...</div></div></div>'
            };
        }

        const techStats = aboutData.stats.tech;
        return {
            title: techStats.modalTitle,
            icon: techStats.modalIcon,
            description: techStats.modalDescription,
            content: generateTimelineHTML()
        };
    }

    /**
     * Get skill level label based on level value
     */
    function getSkillLevelLabel(level) {
        if (!skillLevelsSettings) {
            // Fallback if settings not loaded
            if (level >= 80) return 'Эксперт';
            if (level >= 60) return 'Продвинутый';
            if (level >= 40) return 'Средний';
            return 'Начальный';
        }
        if (level >= skillLevelsSettings.expert.min) return skillLevelsSettings.expert.label;
        if (level >= skillLevelsSettings.advanced.min) return skillLevelsSettings.advanced.label;
        if (level >= skillLevelsSettings.intermediate.min) return skillLevelsSettings.intermediate.label;
        return skillLevelsSettings.beginner.label;
    }


    /**
     * Generate languages modal content from technologies.json
     */
    function generateLanguagesContent() {
        if (!technologiesData || technologiesData.length === 0) {
            return '<div class="languages-section"><p>Загрузка данных...</p></div>';
        }

        // Filter programming languages
        const languages = technologiesData.filter(tech => {
            const flags = tech.flags || {};
            return flags.isProgrammingLanguage === true && !flags.isHidden;
        });

        // Section 1: Currently using (!hasExperience - includes both active and learning)
        const currentLangs = languages.filter(tech => {
            const flags = tech.flags || {};
            return !flags.hasExperience;
        });

        // Section 2: Learning (!hasExperience && isLearning)
        const learningLangs = languages.filter(tech => {
            const flags = tech.flags || {};
            return !flags.hasExperience && flags.isLearning;
        });

        // Section 3: Past experience (hasExperience)
        const pastLangs = languages.filter(tech => {
            const flags = tech.flags || {};
            return flags.hasExperience;
        });


        let html = '';

        // Section 1: Currently using (includes both active and learning)
        if (currentLangs.length > 0) {
            html += `<h4><i class="fas fa-check-circle"></i> Использую сейчас</h4>
            <div class="languages-section current">`;
            currentLangs.forEach(lang => {
                const level = lang.details?.level || 0;
                const levelLabel = getSkillLevelLabel(level);
                const badgeClass = level >= 80 ? 'expert' : level >= 60 ? 'advanced' : level >= 40 ? 'intermediate' : 'beginner';

                html += `
                <div class="language-card">
                    <div class="language-header">
                        <span class="language-name">${lang.name}</span>
                        <span class="language-level ${badgeClass}">${levelLabel}</span>
                    </div>
                    <p class="language-desc">${lang.details?.description || ''}</p>
                    <div class="language-progress">Уровень владения: ${level}%</div>
                </div>`;

            });
            html += '</div>';
        }


        // Section 2: Learning
        if (learningLangs.length > 0) {
            html += `<h4><i class="fas fa-graduation-cap"></i> В процессе изучения</h4>
            <div class="languages-section learning">`;
            learningLangs.forEach(lang => {
                const level = lang.details?.level || 0;
                html += `
                <div class="language-card">
                    <div class="language-header">
                        <span class="language-name">${lang.name}</span>
                        <span class="language-level learning-badge">Изучаю</span>
                    </div>
                    <p class="language-desc">${lang.details?.description || ''}</p>
                    <div class="language-progress">Уровень владения: ${level}%</div>
                </div>`;
            });
            html += '</div>';
        }

        // Section 3: Past experience
        if (pastLangs.length > 0) {
            html += `<h4><i class="fas fa-history"></i> Был опыт в прошлом</h4>
            <div class="languages-section past">`;
            pastLangs.forEach(lang => {
                const years = lang.details?.years || '';
                html += `
                <div class="language-card past-card">
                    <div class="language-header">
                        <span class="language-name">${lang.name}</span>
                        <span class="language-level past-badge">${years}</span>
                    </div>
                    <p class="language-desc">${lang.details?.description || ''}</p>
                </div>`;
            });
            html += '</div>';
        }

        return html;
    }



    /**
     * Get languages stat data
     */
    function getLanguagesStatData() {
        if (!aboutData || !aboutData.stats || !aboutData.stats.languages) {
            return {
                title: 'Языки программирования',
                icon: 'fa-code',
                description: 'Загрузка данных...',
                content: '<div class="languages-section"><p>Загрузка...</p></div>'
            };
        }

        const langStats = aboutData.stats.languages;
        return {
            title: langStats.modalTitle,
            icon: langStats.modalIcon,
            description: langStats.modalDescription,
            content: generateLanguagesContent()
        };
    }

    /**
     * Generate experience modal content from experience.json
     */
    function generateExperienceContent() {
        if (!experienceData || !experienceData.statsModal || !experienceData.statsModal.timeline) {
            return '<div class="growth-list"><div class="growth-item"><div class="growth-content"><p>Загрузка данных...</p></div></div></div>';
        }

        // Create highlighted experience badge
        let experienceBadge = '';
        if (exactExperienceString) {
            experienceBadge = `
                <div class="experience-badge" style="
                    background: linear-gradient(135deg, rgba(139, 92, 246, 0.15), rgba(59, 130, 246, 0.15));
                    border: 1px solid rgba(139, 92, 246, 0.3);
                    border-radius: 12px;
                    padding: 16px 24px;
                    margin-bottom: 24px;
                    text-align: center;
                ">
                    <div style="
                        font-size: 1.5rem;
                        font-weight: 700;
                        color: var(--accent);
                        margin-bottom: 4px;
                    ">
                        <i class="fas fa-clock" style="margin-right: 8px;"></i>${exactExperienceString}
                    </div>
                    <div style="
                        font-size: 0.85rem;
                        color: var(--text-muted);
                    ">общий коммерческий опыт</div>
                </div>
            `;
        }

        const items = experienceData.statsModal.timeline.map(item => `
            <div class="growth-item">
                <div class="growth-period">${item.period}</div>
                <div class="growth-content">
                    <h5>${item.title}</h5>
                    <p>${item.description}</p>
                </div>
            </div>
        `).join('');

        return `${experienceBadge}<div class="growth-list">${items}</div>`;
    }

    /**
     * Calculate exact experience (years and months) from loaded experienceData
     * Synchronous version - uses already loaded data
     */
    function calculateExactExperienceSync() {
        try {
            if (!experienceData) return '';

            const useManualTotal = experienceData.useManualTotal || false;
            const manualTotal = experienceData.manualTotal || '';

            if (useManualTotal && manualTotal) {
                return manualTotal;
            }

            // Merge intervals algorithm (no overlap counting) - синхронизировано с experience.html
            const now = new Date();
            const currentYear = now.getFullYear();
            const currentMonth = now.getMonth() + 1;

            // Convert to intervals [start, end]
            let intervals = experienceData.experience.map(exp => {
                const start = exp.period.start.split('-').map(Number);
                const end = exp.period.isCurrent
                    ? [currentYear, currentMonth]
                    : exp.period.end.split('-').map(Number);
                return { start, end };
            });

            // Sort by start date
            intervals.sort((a, b) => (a.start[0] - b.start[0]) * 12 + (a.start[1] - b.start[1]));

            // Merge overlapping intervals
            let merged = [];
            for (let interval of intervals) {
                if (merged.length === 0 || merged[merged.length - 1].end[0] * 12 + merged[merged.length - 1].end[1] < interval.start[0] * 12 + interval.start[1]) {
                    merged.push(interval);
                } else {
                    // Extend end date to max of both intervals
                    const currentEndMonths = merged[merged.length - 1].end[0] * 12 + merged[merged.length - 1].end[1];
                    const newEndMonths = interval.end[0] * 12 + interval.end[1];
                    if (newEndMonths > currentEndMonths) {
                        const newEndTotalMonths = newEndMonths;
                        merged[merged.length - 1].end[0] = Math.floor(newEndTotalMonths / 12);
                        merged[merged.length - 1].end[1] = (newEndTotalMonths % 12) || 12;
                    }
                }
            }

            // Calculate total months from merged intervals
            let totalMonths = 0;
            merged.forEach(({ start, end }) => {
                totalMonths += (end[0] - start[0]) * 12 + (end[1] - start[1]);
            });

            const years = Math.floor(totalMonths / 12);
            const months = totalMonths % 12;

            // Format the result (точно как в experience.html)
            let result = '';
            if (years > 0) {
                if (years === 1 || (years > 20 && years % 10 === 1)) {
                    result = years + ' год';
                } else if ((years >= 2 && years <= 4) || (years > 20 && years % 10 >= 2 && years % 10 <= 4)) {
                    result = years + ' года';
                } else {
                    result = years + ' лет';
                }

                if (months > 0) {
                    if (months === 1 || (months > 20 && months % 10 === 1)) {
                        result += ' ' + months + ' месяц';
                    } else if ((months >= 2 && months <= 4) || (months > 20 && months % 10 >= 2 && months % 10 <= 4)) {
                        result += ' ' + months + ' месяца';
                    } else {
                        result += ' ' + months + ' месяцев';
                    }
                }
            } else {
                if (months === 1 || (months > 20 && months % 10 === 1)) {
                    result = months + ' месяц';
                } else if ((months >= 2 && months <= 4) || (months > 20 && months % 10 >= 2 && months % 10 <= 4)) {
                    result = months + ' месяца';
                } else {
                    result = months + ' месяцев';
                }
            }

            return result;

        } catch (error) {
            console.error('StatsModal: failed to calculate exact experience', error);
            return '';
        }
    }

    /**
     * Get experience stat data
     */
    function getExperienceStatData() {
        if (!aboutData || !aboutData.stats || !aboutData.stats.experience) {
            return {
                title: 'Путь развития',
                icon: 'fa-chart-line',
                description: 'Загрузка данных...',
                content: '<div class="growth-list"><div class="growth-item"><div class="growth-content"><p>Загрузка...</p></div></div></div>'
            };
        }

        const expStats = aboutData.stats.experience;

        return {
            title: expStats.modalTitle,
            icon: expStats.modalIcon,
            description: expStats.modalDescription,
            content: generateExperienceContent()
        };
    }

    /**
     * Generate projects modal content from projects.json
     */
    function generateProjectsContent() {
        if (!projectsData || !projectsData.projects || projectsData.projects.length === 0) {
            return '<div class="challenges-list"><div class="challenge-item"><div class="challenge-solution"><p>Загрузка данных...</p></div></div></div>';
        }

        const items = projectsData.projects.map(project => `
            <div class="challenge-item">
                <div class="challenge-project">${project.title}</div>
                <div class="challenge-solution">${project.description}</div>
            </div>
        `).join('');

        return `<div class="challenges-list">${items}</div>`;
    }

    /**
     * Get projects stat data
     */
    function getProjectsStatData() {
        if (!aboutData || !aboutData.stats || !aboutData.stats.projects) {
            return {
                title: 'Технические вызовы',
                icon: 'fa-mountain',
                description: 'Загрузка данных...',
                content: '<div class="challenges-list"><div class="challenge-item"><div class="challenge-solution"><p>Загрузка...</p></div></div></div>'
            };
        }

        const projStats = aboutData.stats.projects;

        return {
            title: projStats.modalTitle,
            icon: projStats.modalIcon,
            description: projStats.modalDescription,
            content: generateProjectsContent()
        };
    }






    // Data for each stat modal
    const statsData = {
        get tech() {
            return getTechStatData();
        },

        get languages() {
            return getLanguagesStatData();
        },

        get experience() {
            return getExperienceStatData();
        },

        get projects() {
            return getProjectsStatData();
        }

    };

    // DOM Elements
    let modal = null;
    let modalTitle = null;
    let modalDescription = null;
    let modalContent = null;
    let modalClose = null;
    let modalCloseBtn = null;

    // Initialize
    async function init() {
        await loadAboutData();
        createModal();
        bindEvents();
        animateCounters();
    }


    // Create modal HTML structure
    function createModal() {
        modal = document.createElement('div');
        modal.id = 'statsModal';
        modal.innerHTML = `
            <div class="modal-content">
                <div class="modal-header">
                    <h3 id="statsModalTitle"><i class="fas" style="color: var(--accent); margin-right: 0.5rem;"></i><span></span></h3>
                    <button class="modal-close" id="statsModalClose">&times;</button>
                </div>
                <div class="modal-body">
                    <div class="stats-modal-description" id="statsModalDescription"></div>
                    <div class="stats-modal-content" id="statsModalContent"></div>
                </div>
                <div class="modal-footer">
                    <button class="modal-btn modal-btn-secondary" id="statsModalCloseBtn">Закрыть</button>
                </div>
            </div>
        `;
        document.body.appendChild(modal);

        // Cache elements
        modalTitle = modal.querySelector('#statsModalTitle');
        modalDescription = modal.querySelector('#statsModalDescription');
        modalContent = modal.querySelector('#statsModalContent');
        modalClose = modal.querySelector('#statsModalClose');
        modalCloseBtn = modal.querySelector('#statsModalCloseBtn');
    }

    // Bind events
    function bindEvents() {
        // Stat item clicks
        document.querySelectorAll('.stat-item').forEach(item => {
            item.addEventListener('click', () => {
                const statType = item.dataset.stat;
                openModal(statType);
            });
        });

        // Close buttons
        modalClose.addEventListener('click', closeModal);
        modalCloseBtn.addEventListener('click', closeModal);

        // Click outside to close
        modal.addEventListener('click', (e) => {
            if (e.target === modal) {
                closeModal();
            }
        });

        // Escape key
        document.addEventListener('keydown', (e) => {
            if (e.key === 'Escape' && modal.classList.contains('active')) {
                closeModal();
            }
        });
    }

    // Open modal with specific stat data
    function openModal(statType) {
        const data = statsData[statType];
        if (!data) return;

        // Set content
        modalTitle.querySelector('i').className = `fas ${data.icon}`;
        modalTitle.querySelector('span').textContent = data.title;
        modalDescription.textContent = data.description;
        modalContent.innerHTML = data.content;

        // Show modal
        modal.classList.remove('closing');
        modal.classList.add('active');
        document.body.style.overflow = 'hidden';
    }

    // Close modal
    function closeModal() {
        modal.classList.add('closing');
        modal.classList.remove('active');
        document.body.style.overflow = '';

        setTimeout(() => {
            modal.classList.remove('closing');
        }, 300);
    }

    // Animate counters on scroll
    function animateCounters() {
        const counters = document.querySelectorAll('.stat-number');
        const observerOptions = {
            threshold: 0.5,
            rootMargin: '0px'
        };

        const observer = new IntersectionObserver((entries) => {
            entries.forEach(entry => {
                if (entry.isIntersecting) {
                    const counter = entry.target;
                    const target = parseInt(counter.dataset.target);
                    animateCount(counter, target);
                    observer.unobserve(counter);
                }
            });
        }, observerOptions);

        counters.forEach(counter => observer.observe(counter));
    }

    // Count up animation
    function animateCount(element, target) {
        const duration = 1500;
        const start = 0;
        const startTime = performance.now();

        function update(currentTime) {
            const elapsed = currentTime - startTime;
            const progress = Math.min(elapsed / duration, 1);

            // Easing function (ease-out)
            const easeOut = 1 - Math.pow(1 - progress, 3);
            const current = Math.floor(start + (target - start) * easeOut);

            element.textContent = current;

            if (progress < 1) {
                requestAnimationFrame(update);
            } else {
                element.textContent = target;
            }
        }

        requestAnimationFrame(update);
    }

    // Initialize when DOM is ready
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }
})();


// === share-modal.js ===
// Share - uses native navigator.share() where available
(function () {
    document.querySelectorAll('.site-share-btn, .project-share-btn').forEach(btn => {
        btn.addEventListener('click', async () => {
            const projectCard = btn.closest('.project-card');
            const title = projectCard?.querySelector('h3')?.textContent || 'Backend / Fullstack Разработчик / Программный инженер / Менеджер по ИТ';
            const url = projectCard?.dataset.url || window.location.href;

            if (navigator.share) {
                try {
                    await navigator.share({ title, url });
                } catch (err) {
                    if (err.name !== 'AbortError') console.warn('Share failed:', err);
                }
            } else {
                // Fallback: copy to clipboard
                try {
                    await navigator.clipboard.writeText(url);
                    const icon = btn.querySelector('i');
                    if (icon) {
                        icon.className = 'fas fa-check';
                        setTimeout(() => { icon.className = 'fas fa-share-alt'; }, 1500);
                    }
                } catch (err) {
                    console.warn('Copy failed:', err);
                }
            }
        });
    });
})();



// Global function for project page
window.openLightbox = function (projectImages, startIndex, projectName) {
    images = projectImages.map(img => ({
        src: img.src,
        getAttribute: (attr) => {
            if (attr === 'data-title') return img.title;
            if (attr === 'data-desc') return img.desc;
            return img.alt || img.title;
        },
        alt: img.title || ''
    }));
    currentIndex = startIndex;
    currentProjectName = projectName;
    showLightbox();
};
